import { InvalidRequestError, InvalidTransitionError } from "./domain-errors";
import { OrderLine } from "./order-line";
import { OrderState, canCancelFrom, nextState } from "./order-state";

export class Order {
  private currentState: OrderState = "placed";
  private cancelledFlag = false;

  constructor(
    readonly id: string,
    readonly customerId: string,
    readonly lines: readonly OrderLine[],
  ) {
    if (lines.length === 0) throw new InvalidRequestError("An order needs at least one line");
  }

  get state(): OrderState {
    return this.currentState;
  }

  get cancelled(): boolean {
    return this.cancelledFlag;
  }

  advance(): OrderState {
    if (this.cancelledFlag) throw new InvalidTransitionError("Order is cancelled");
    const next = nextState(this.currentState);
    if (!next) throw new InvalidTransitionError(`Order is already ${this.currentState}`);
    this.currentState = next;
    return next;
  }

  moveTo(target: OrderState): void {
    if (this.cancelledFlag) throw new InvalidTransitionError("Order is cancelled");
    if (nextState(this.currentState) !== target) {
      throw new InvalidTransitionError(`Cannot move order from ${this.currentState} to ${target}`);
    }
    this.currentState = target;
  }

  cancel(): void {
    if (this.cancelledFlag) throw new InvalidTransitionError("Order is already cancelled");
    if (!canCancelFrom(this.currentState)) {
      throw new InvalidTransitionError(`Order cannot be cancelled once ${this.currentState}`);
    }
    this.cancelledFlag = true;
  }
}

