import { InsufficientStockError, InvalidRequestError } from "./domain-errors";

export class Product {
  private available: number;
  private reserved = 0;

  constructor(
    readonly id: string,
    readonly name: string,
    initialStock: number,
  ) {
    if (!Number.isInteger(initialStock) || initialStock < 0) {
      throw new InvalidRequestError("Initial stock must be a non-negative integer");
    }
    this.available = initialStock;
  }

  get availableStock(): number {
    return this.available;
  }

  get reservedStock(): number {
    return this.reserved;
  }

  canReserve(quantity: number): boolean {
    return quantity <= this.available;
  }

  reserve(quantity: number): void {
    if (!this.canReserve(quantity)) throw new InsufficientStockError(this.id);
    this.available -= quantity;
    this.reserved += quantity;
  }

  release(quantity: number): void {
    const released = Math.min(quantity, this.reserved);
    this.reserved -= released;
    this.available += released;
  }
}

